typedef unsigned char u_char;
typedef unsigned int u_int;
typedef unsigned long u_long;
typedef unsigned int u_long128 __attribute__((mode(TI)));

struct Rect
{
    int x;
    int y;
    int w;
    int h;
};

struct sceGifPacket;

extern "C" void sceGifPkInit(sceGifPacket*, u_long128*);
extern "C" void sceGifPkReset(sceGifPacket*);
extern "C" void sceGifPkCnt(sceGifPacket*, int, int, int);
extern "C" void sceGifPkOpenGifTag(sceGifPacket*, u_long128);
extern "C" void sceGifPkAddGsAD(sceGifPacket*, int, u_long);
extern "C" void sceGifPkCloseGifTag(sceGifPacket*);
extern "C" void* sceGifPkReserve(sceGifPacket*, int);
extern "C" void sceGifPkRef(sceGifPacket*, u_long128*, int, int, int, int);
extern "C" void sceGifPkEnd(sceGifPacket*, int, int, int);
extern "C" void sceGifPkTerminate(sceGifPacket*);

#define UNCMASK 0x0fffffff
#define UNCBASE 0x20000000
#define MAX_WIDTH 720
#define MAX_HEIGHT 576
#define bound(val,x) ((((val) + (x) - 1) / (x))*(x))
#define SCE_GS_PSMCT32 0
#define SCE_GS_BITBLTBUF 0x50
#define SCE_GS_TRXPOS 0x51
#define SCE_GS_TRXREG 0x52
#define SCE_GS_TRXDIR 0x53
#define SCE_GS_TEX0_1 0x06
#define SCE_GS_TEX1_1 0x14
#define SCE_GS_TEXFLUSH 0x3f
#define SCE_GS_PRIM 0x00
#define SCE_GS_UV 0x03
#define SCE_GS_XYZ2 0x05
#define SCE_GIF_SET_TAG(nloop,eop,pre,prim,flg,nreg) ((u_long)(nloop) | ((u_long)(eop)<<15) | ((u_long)(pre)<<46) | ((u_long)(prim)<<47) | ((u_long)(flg)<<58) | ((u_long)(nreg)<<60))
#define SCE_GS_SET_BITBLTBUF(sbp,sbw,spsm,dbp,dbw,dpsm) ((u_long)(sbp) | ((u_long)(sbw)<<16) | ((u_long)(spsm)<<24) | ((u_long)(dbp)<<32) | ((u_long)(dbw)<<48) | ((u_long)(dpsm)<<56))
#define SCE_GS_SET_TRXPOS(ssax,ssay,dsax,dsay,dir) ((u_long)(ssax) | ((u_long)(ssay)<<16) | ((u_long)(dsax)<<32) | ((u_long)(dsay)<<48) | ((u_long)(dir)<<59))
#define SCE_GS_SET_TRXREG(rrw,rrh) ((u_long)(rrw) | ((u_long)(rrh)<<32))
#define SCE_GS_SET_TRXDIR(xdir) ((u_long)(xdir))
#define SCE_GS_SET_TEX1_1(lcm,mxl,mmag,mmin,mtba,l,k) ((u_long)(lcm) | ((u_long)(mxl)<<2) | ((u_long)(mmag)<<5) | ((u_long)(mmin)<<6) | ((u_long)(mtba)<<9) | ((u_long)(l)<<19) | ((u_long)(k)<<32))
#define SCE_GS_SET_TEX0_1(tbp0,tbw,psm,tw,th,tcc,tfx,cbp,cpsm,csm,csa,cld) ((u_long)(tbp0) | ((u_long)(tbw)<<14) | ((u_long)(psm)<<20) | ((u_long)(tw)<<26) | ((u_long)(th)<<30) | ((u_long)(tcc)<<34) | ((u_long)(tfx)<<35) | ((u_long)(cbp)<<37) | ((u_long)(cpsm)<<51) | ((u_long)(csm)<<55) | ((u_long)(csa)<<56) | ((u_long)(cld)<<61))
#define SCE_GS_SET_PRIM(prim,iip,tme,fge,abe,aa1,fst,ctxt,fix) ((u_long)(prim) | ((u_long)(iip)<<3) | ((u_long)(tme)<<4) | ((u_long)(fge)<<5) | ((u_long)(abe)<<6) | ((u_long)(aa1)<<7) | ((u_long)(fst)<<8) | ((u_long)(ctxt)<<9) | ((u_long)(fix)<<10))
#define SCE_GS_SET_UV(u,v) ((u_long)(u) | ((u_long)(v)<<16))
#define SCE_GS_SET_XYZ2(x,y,z) ((u_long)(x) | ((u_long)(y)<<16) | ((u_long)(z)<<32))

static inline void *UncAddr( void *val )
{
    return (void*)(((unsigned)val & UNCMASK) | UNCBASE );
}

static inline void *DmaAddr( void *val )
{
    return (void*)( (unsigned)val & UNCMASK );
}

static void setImageTag( u_int *tags, void *image, int index, int image_w, int image_h )
{
    const u_long    giftag[2] = { SCE_GIF_SET_TAG(0, 0, 0, 0, 0, 1), 0x000000000000000eL },
                    giftag_eop[2] = { SCE_GIF_SET_TAG(0, 1, 0, 0, 0, 1), 0x000000000000000eL };
    u_int           dbp, dbw, dpsm, dir, dsax, dsay, rrw, rrh, xdir;
    int             mbx = image_w >> 4, mby = image_h >> 4;
    Rect            tex, poly;
    sceGifPacket    packet;	

    sceGifPkInit( &packet, (u_long128*)UncAddr(tags) );
    sceGifPkReset( &packet );
    if( index == 0 )
    {
        dbp = ( bound(MAX_WIDTH, 64) * bound((MAX_HEIGHT / 2), 32) * 2 ) / 64;
        dbw = bound( MAX_WIDTH, 64 ) / 64;
        dpsm = SCE_GS_PSMCT32;
        dir = 0;
        dsax = 0;
        dsay = 0;
        rrw = 16;
        rrh = 16;
        xdir = 0;
        sceGifPkCnt(&packet, 0, 0, 0);
        sceGifPkOpenGifTag( &packet, *(u_long128*)&giftag );
        sceGifPkAddGsAD( &packet, SCE_GS_BITBLTBUF, SCE_GS_SET_BITBLTBUF(0, 0, 0, dbp, dbw, dpsm) );
        sceGifPkAddGsAD( &packet, SCE_GS_TRXREG, SCE_GS_SET_TRXREG(rrw, rrh));
        sceGifPkCloseGifTag( &packet );
        for( int i = 0; i < mbx; i++ )
        {
            for( int j = 0; j < mby; j++ )
            {
                sceGifPkCnt( &packet, 0, 0, 0 );
                sceGifPkOpenGifTag( &packet, *(u_long128*)giftag );
                sceGifPkAddGsAD( &packet, SCE_GS_TRXPOS, SCE_GS_SET_TRXPOS(0, 0, 16*i+dsax, 16*j+dsay, 0) );
                sceGifPkAddGsAD( &packet, SCE_GS_TRXDIR, SCE_GS_SET_TRXDIR(xdir) );
                sceGifPkCloseGifTag( &packet );
                u_long* const   tag = (u_long*)sceGifPkReserve( &packet, 4 );
                tag[0] = SCE_GIF_SET_TAG( 16 * 16 * 4 / 16, 0, 0, 0, 2, 0 );
                tag[1] = 0;
                sceGifPkRef( &packet, (u_long128*)DmaAddr(image), 16 * 16 * 4 / 16, 0, 0, 0 );
                image = (u_char*)image + 16 * 16 * 4;
            }
        }
    }

    tex.x = 8;
    tex.y = 8;
    tex.w = image_w << 4;
    tex.h = image_h << 4;

    poly.x = ( 2048 - (image_w >> 1) ) << 4;
    poly.y = ( 2048 - (image_h >> 2) ) << 4;
    poly.w = image_w << 4;
    poly.h = image_h << 3;

    sceGifPkEnd(&packet, 0, 0, 0);

    sceGifPkOpenGifTag( &packet, *(u_long128*)giftag_eop );
    sceGifPkAddGsAD( &packet, SCE_GS_TEXFLUSH, 0 );
    sceGifPkAddGsAD( &packet, SCE_GS_TEX1_1, SCE_GS_SET_TEX1_1(0, 0, 1, 1, 0, 0, 0) );
    sceGifPkAddGsAD( &packet, SCE_GS_TEX0_1, SCE_GS_SET_TEX0_1((bound(MAX_WIDTH, 64) * bound((MAX_HEIGHT/2), 32) * 2)/64, bound(MAX_WIDTH, 64)/64, SCE_GS_PSMCT32, 10, 10, 0, 1, 0, 0, 0, 0, 0) );
    sceGifPkAddGsAD( &packet, SCE_GS_PRIM, SCE_GS_SET_PRIM(6, 0, 1, 0, 0, 0, 1, 0, 0) );
    sceGifPkAddGsAD( &packet, SCE_GS_UV, SCE_GS_SET_UV(tex.x, tex.y) ); 
    sceGifPkAddGsAD( &packet, SCE_GS_XYZ2, SCE_GS_SET_XYZ2(poly.x, poly.y, 0) ); 
    sceGifPkAddGsAD( &packet, SCE_GS_UV, SCE_GS_SET_UV(tex.x + tex.w, tex.y + tex.h) ); 
    sceGifPkAddGsAD( &packet, SCE_GS_XYZ2, SCE_GS_SET_XYZ2(poly.x + poly.w, poly.y + poly.h, 0) );
    sceGifPkCloseGifTag( &packet );
    sceGifPkTerminate( &packet );
}
